
#define main archived_sosfil_main
#include "../sosfil-cuda/main.cu"
#undef main
#include <string>
#include <algorithm>
std::vector<double> readfile(const char*name,int n){std::vector<double>v(n);FILE*f=fopen(name,"rb");if(!f||fread(v.data(),8,n,f)!=size_t(n)){fprintf(stderr,"Bad file %s\n",name);exit(2);}fclose(f);return v;}
struct Base{virtual void resetwarm(std::vector<double>&)=0;virtual double timed()=0;virtual void capture(std::vector<double>&)=0;virtual~Base(){};};
template<class T>struct Case:Base{int signals,samples,shared;std::vector<T>sos,zi,x,cpu;T*ds,*dz,*dx;Case(std::vector<double>&p,size_t&pos){int bits=p[pos++];signals=p[pos++];samples=p[pos++];pos+=2;shared=p[pos++];for(int i=0;i<384;i++)sos.push_back(T(p[pos++]));for(int i=0;i<signals*128;i++)zi.push_back(T(p[pos++]));for(int i=0;i<signals*samples;i++)x.push_back(T(p[pos++]));cudaCheck(cudaMalloc(&ds,384*sizeof(T)));cudaCheck(cudaMalloc(&dz,zi.size()*sizeof(T)));cudaCheck(cudaMalloc(&dx,x.size()*sizeof(T)));cudaCheck(cudaMemcpy(ds,sos.data(),384*sizeof(T),cudaMemcpyHostToDevice));cudaCheck(cudaMemcpy(dz,zi.data(),zi.size()*sizeof(T),cudaMemcpyHostToDevice));cudaCheck(cudaMemcpy(dx,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));launch();}void launch(){sosfilt<T><<<signals,64,shared*sizeof(T)>>>(signals,samples,64,2,ds,dz,dx);}void capture(std::vector<double>&v){std::vector<T>b(x.size());cudaCheck(cudaMemcpy(b.data(),dx,b.size()*sizeof(T),cudaMemcpyDeviceToHost));for(auto a:b)v.push_back(double(a));}void resetwarm(std::vector<double>&v){cpu=x;cudaCheck(cudaMemcpy(dx,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));for(int i=0;i<2;i++){launch();cudaCheck(cudaDeviceSynchronize());reference<T>(signals,samples,64,2,sos.data(),zi.data(),cpu.data());std::vector<double>b;capture(b);for(size_t j=0;j<b.size();j++)if(!std::isfinite(b[j])||fabs(b[j]-double(cpu[j]))>1e-4+1e-4*fabs(double(cpu[j])))exit(4);v.insert(v.end(),b.begin(),b.end());}}double timed(){cudaCheck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int i=0;i<3;i++)launch();cudaCheck(cudaGetLastError());cudaCheck(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;}~Case(){cudaFree(ds);cudaFree(dz);cudaFree(dx);}};
int main(){auto prefix=readfile("study_input_f64.bin",4642);auto gold=readfile("study_expected_f64.bin",5406);size_t pos=0;std::vector<Base*>cs;cs.push_back(new Case<float>(prefix,pos));cs.push_back(new Case<float>(prefix,pos));cs.push_back(new Case<double>(prefix,pos));cs.push_back(new Case<double>(prefix,pos));cudaCheck(cudaDeviceSynchronize());bool all=true;
 for(int trial=1;trial<=5;trial++){std::vector<std::vector<double>>v(4);for(int i=0;i<4;i++)cs[i]->resetwarm(v[i]);double time=0;for(auto*c:cs)time+=c->timed();auto out=prefix;size_t k=0;bool ok=true;double maxerr=0;for(int i=0;i<4;i++){cs[i]->capture(v[i]);for(auto x:v[i]){double g=gold[k++];maxerr=std::max(maxerr,fabs(x-g));ok&=std::isfinite(x)&&fabs(x-g)<=1e-4+1e-4*fabs(g);out.push_back(x);}}all&=ok;std::string path=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");if(!f)return 5;fwrite(out.data(),8,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":5406,\"max_abs_error\":%.12g,\"max_rel_error\":0,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,time,ok?"true":"false",maxerr,path.c_str(),out.size());}for(auto*c:cs)delete c;puts(all?"PASS":"FAIL");return 0;}
